    ApplyPendingMaintenanceActionMessage.add_member(:opt_in_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptInType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A value that specifies the type of opt-in request, or undoes an opt-in request. An opt-in\n      request of type <code>immediate</code> can't be undone.</p>\n         <p>Valid values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>immediate</code> - Apply the maintenance action immediately.</p>\n            </li>\n            <li>\n               <p>\n                  <code>next-maintenance</code> - Apply the maintenance action during the next\n          maintenance window for the resource.</p>\n            </li>\n            <li>\n               <p>\n                  <code>undo-opt-in</code> - Cancel any existing <code>next-maintenance</code> opt-in\n          requests.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
