    ClusterPendingModifiedValues.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The pending change in storage type for the DB cluster.   Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>standard</code>\n                  </b>   –  \n        ( <i>the default</i> ) Configures cost-effective database storage for applications\n        with moderate to small I/O usage.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>iopt1</code>\n                  </b>   –  \n          Enables <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/storage-types.html#provisioned-iops-storage\">I/O-Optimized storage</a>\n          that's designed to meet the needs of I/O-intensive graph workloads that\n          require predictable pricing with low I/O latency and consistent I/O throughput.</p>\n               <p>Neptune I/O-Optimized storage is only available starting with engine release 1.3.0.0.</p>\n            </li>\n         </ul>"}))
    ClusterPendingModifiedValues.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The allocated storage size in gibibytes (GiB) for database engines. For Neptune,\n      <code>AllocatedStorage</code> always returns 1, because Neptune DB cluster storage size isn't fixed, but\n        instead automatically adjusts as needed.</p>"}))
    ClusterPendingModifiedValues.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The Provisioned IOPS (I/O operations per second) value. This setting is only for Multi-AZ DB clusters.</p>"}))
