    CreateDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the instances in the DB cluster accept connections.</p>\n         <p> Default: <code>8182</code>\n         </p>"}))
