    CreateDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>Not supported by Neptune.</p>"}))
    CreateDBClusterMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>\n            <i>(Not supported by Neptune)</i>\n         </p>"}))
    CreateDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created if automated backups are\n      enabled using the <code>BackupRetentionPeriod</code> parameter.</p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n      Amazon Region. To see the time blocks available, see <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/manage-console-maintaining.html#manage-console-maintaining-window\">Neptune\n      Maintenance Window</a> in the <i>Amazon Neptune User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated\n      Time (UTC).</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n      Amazon Region, occurring on a random day of the week. To see the time blocks available, see <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/manage-console-maintaining.html#manage-console-maintaining-window\">Neptune\n      Maintenance Window</a> in the <i>Amazon Neptune User Guide.</i>\n         </p>\n         <p>Valid Days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    CreateDBClusterMessage.add_member(:replication_source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationSourceIdentifier', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the source DB instance or DB cluster if this DB cluster\n      is created as a Read Replica.</p>"}))
    CreateDBClusterMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to assign to the new DB cluster.</p>"}))
    CreateDBClusterMessage.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster is encrypted.</p>"}))
    CreateDBClusterMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon KMS key identifier for an encrypted DB cluster.</p>\n         <p>The KMS key identifier is the Amazon Resource Name (ARN) for the KMS encryption key. If\n      you are creating a DB cluster with the same Amazon account that owns the KMS encryption key used\n      to encrypt the new DB cluster, then you can use the KMS key alias instead of the ARN for the\n      KMS encryption key.</p>\n         <p>If an encryption key is not specified in <code>KmsKeyId</code>:</p>\n         <ul>\n            <li>\n               <p>If <code>ReplicationSourceIdentifier</code> identifies an encrypted source, then\n          Amazon Neptune will use the encryption key used to encrypt the source. Otherwise, Amazon\n          Neptune will use your default encryption key.</p>\n            </li>\n            <li>\n               <p>If the <code>StorageEncrypted</code> parameter is true and\n          <code>ReplicationSourceIdentifier</code> is not specified, then Amazon Neptune will use\n          your default encryption key.</p>\n            </li>\n         </ul>\n         <p>Amazon KMS creates the default encryption key for your Amazon account. Your Amazon account has a\n      different default encryption key for each Amazon Region.</p>\n         <p>If you create a Read Replica of an encrypted DB cluster in another Amazon Region, you must\n      set <code>KmsKeyId</code> to a KMS key ID that is valid in the destination Amazon Region. This\n      key is used to encrypt the Read Replica in that Amazon Region.</p>"}))
    CreateDBClusterMessage.add_member(:pre_signed_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreSignedUrl', traits: {"smithy.api#documentation" => "<p>This parameter is not currently supported.</p>"}))
    CreateDBClusterMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>If set to <code>true</code>, enables Amazon Identity and Access Management\n      (IAM) authentication for the entire DB cluster (this cannot be set at an\n      instance level).</p>\n         <p>Default: <code>false</code>.</p>"}))
    CreateDBClusterMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>A list of the log types that this DB cluster should export to CloudWatch Logs.\n      Valid log types are: <code>audit</code> (to publish audit logs) and\n      <code>slowquery</code> (to publish slow-query logs). See <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/cloudwatch-logs.html\">Publishing Neptune logs\n      to Amazon CloudWatch logs</a>.</p>"}))
    CreateDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>A value that indicates whether the DB cluster has deletion protection enabled.\n      The database can't be deleted when deletion protection is enabled. By default,\n      deletion protection is enabled.</p>"}))
    CreateDBClusterMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>Contains the scaling configuration of a Neptune Serverless DB cluster.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/neptune-serverless-using.html\">Using Amazon Neptune Serverless</a> in the\n      <i>Amazon Neptune User Guide</i>.</p>"}))
    CreateDBClusterMessage.add_member(:global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: GlobalClusterIdentifier, location_name: 'GlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The ID of the Neptune global database to which this new DB cluster\n      should be added.</p>"}))
    CreateDBClusterMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type for the new DB cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>standard</code>\n                  </b>   –  \n        ( <i>the default</i> ) Configures cost-effective database storage for applications\n        with moderate to small I/O usage. When set to <code>standard</code>, the storage type\n        is not returned in the response.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>iopt1</code>\n                  </b>   –  \n          Enables <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/storage-types.html#provisioned-iops-storage\">I/O-Optimized storage</a>\n          that's designed to meet the needs of I/O-intensive graph workloads that\n          require predictable pricing with low I/O latency and consistent I/O throughput.</p>\n               <p>Neptune I/O-Optimized storage is only available starting with engine release 1.3.0.0.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.type = Types::CreateDBClusterMessage
