    CreateDBInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The time range each week during which system maintenance can occur, in Universal\n      Coordinated Time (UTC).</p>\n         <p> Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n      Amazon Region, occurring on a random day of the week.</p>\n         <p>Valid Days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    CreateDBInstanceMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this DB instance. If this argument is\n      omitted, the default DBParameterGroup for the specified engine is used.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are\n      retained.</p>\n         <p>Not applicable. The retention period for automated backups is managed by the DB cluster.\n      For more information, see <a>CreateDBCluster</a>.</p>\n         <p>Default: 1</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 0 to 35</p>\n            </li>\n            <li>\n               <p>Cannot be set to 0 if the DB instance is a source to Read Replicas</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p> The daily time range during which automated backups are created.</p>\n         <p>Not applicable. The daily time range for creating automated backups is managed by the DB\n      cluster. For more information, see <a>CreateDBCluster</a>.</p>"}))
