    CreateDBInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Indicates that minor engine upgrades are applied automatically to the DB instance during\n      the maintenance window.</p>\n         <p>Default: <code>true</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>License model information for this DB instance.</p>\n         <p> Valid values: <code>license-included</code> | <code>bring-your-own-license</code> |\n      <code>general-public-license</code>\n         </p>"}))
