    CreateDBInstanceMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected\n      for the DB instance. To disable collecting Enhanced Monitoring metrics, specify 0. The default\n      is 0.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, then you must also set\n      <code>MonitoringInterval</code> to a value other than 0.</p>\n         <p>Valid Values: <code>0, 1, 5, 10, 15, 30, 60</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits Neptune to send enhanced monitoring metrics to\n      Amazon CloudWatch Logs. For example,\n      <code>arn:aws:iam:123456789012:role/emaccess</code>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than 0, then you must supply a\n      <code>MonitoringRoleArn</code> value.</p>"}))
