    CreateDBInstanceMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>A value that indicates whether the DB instance has deletion protection enabled.\n      The database can't be deleted when deletion protection is enabled. By default,\n      deletion protection is disabled. See <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/manage-console-instances-delete.html\">Deleting\n      a DB Instance</a>.</p>\n         <p>DB instances in a DB cluster can be deleted even when deletion\n      protection is enabled in their parent DB cluster.</p>"}))
