    ModifyDBClusterMessage.add_member(:new_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The new DB cluster identifier for the DB cluster when renaming a DB cluster. This value is\n      stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>The first character must be a letter</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster2</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>A value that specifies whether the modifications in this request and any pending\n      modifications are asynchronously applied as soon as possible, regardless of the\n      <code>PreferredMaintenanceWindow</code> setting for the DB cluster. If this parameter is set\n      to <code>false</code>, changes to the DB cluster are applied during the next maintenance\n      window.</p>\n         <p>The <code>ApplyImmediately</code> parameter only affects <code>NewDBClusterIdentifier</code>\n      values. If you set the <code>ApplyImmediately</code> parameter value to false, then changes to\n      <code>NewDBClusterIdentifier</code> values are applied during the next maintenance window.\n      All other changes are applied immediately, regardless of the value of the\n      <code>ApplyImmediately</code> parameter.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained. You must specify a minimum\n      value of 1.</p>\n         <p>Default: 1</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 1 to 35</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group to use for the DB cluster.</p>"}))
    ModifyDBClusterMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of VPC security groups that the DB cluster will belong to.</p>"}))
    ModifyDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the DB cluster accepts connections.</p>\n         <p>Constraints: Value must be <code>1150-65535</code>\n         </p>\n         <p>Default: The same port as the original DB cluster.</p>"}))
    ModifyDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>Not supported by Neptune.</p>"}))
    ModifyDBClusterMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>\n            <i>Not supported by Neptune.</i>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created if automated backups are\n      enabled, using the <code>BackupRetentionPeriod</code> parameter.</p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n      Amazon Region.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated\n      Time (UTC).</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n      Amazon Region, occurring on a random day of the\n      week.</p>\n         <p>Valid Days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    ModifyDBClusterMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>True to enable mapping of Amazon Identity and Access Management (IAM) accounts to database\n      accounts, and otherwise false.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:cloudwatch_logs_export_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudwatchLogsExportConfiguration, location_name: 'CloudwatchLogsExportConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration setting for the log types to be enabled for export to CloudWatch Logs\n      for a specific DB cluster. See <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/cloudwatch-logs.html#cloudwatch-logs-cli\">Using the\n      CLI to publish Neptune audit logs to CloudWatch Logs</a>.</p>"}))
    ModifyDBClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to which you want to upgrade. Changing this\n      parameter results in an outage. The change is applied during the next maintenance window\n      unless the <code>ApplyImmediately</code> parameter is set to true.</p>\n         <p>For a list of valid engine versions, see <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/engine-releases.html\">Engine Releases for Amazon\n      Neptune</a>, or call <a>DescribeDBEngineVersions</a>.</p>"}))
    ModifyDBClusterMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>A value that indicates whether upgrades between different major versions are allowed.</p>\n         <p>Constraints: You must set the allow-major-version-upgrade flag when providing an\n      <code>EngineVersion</code> parameter that uses a different major version than the DB cluster's current\n      version.</p>"}))
    ModifyDBClusterMessage.add_member(:db_instance_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to apply to all instances of the DB cluster. </p>\n         <note>\n            <p>When you apply a parameter group using <code>DBInstanceParameterGroupName</code>,\n      parameter changes aren't applied during the next maintenance window but instead are\n      applied immediately.</p>\n         </note>\n         <p>Default: The existing name setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>The DB parameter group must be in the same DB parameter group family as\n        the target DB cluster version.</p>\n            </li>\n            <li>\n               <p>The <code>DBInstanceParameterGroupName</code> parameter is only valid in combination with\n        the <code>AllowMajorVersionUpgrade</code> parameter.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>A value that indicates whether the DB cluster has deletion protection enabled.\n      The database can't be deleted when deletion protection is enabled. By default,\n      deletion protection is disabled.</p>"}))
    ModifyDBClusterMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>\n            <i>If set to <code>true</code>, tags are copied to any snapshot of\n      the DB cluster that is created.</i>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>Contains the scaling configuration of a Neptune Serverless DB cluster.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/neptune-serverless-using.html\">Using Amazon Neptune Serverless</a> in the\n      <i>Amazon Neptune User Guide</i>.</p>"}))
    ModifyDBClusterMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>standard</code>\n                  </b>   –  \n        ( <i>the default</i> ) Configures cost-effective database storage for applications\n        with moderate to small I/O usage.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>iopt1</code>\n                  </b>   –  \n          Enables <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/storage-types.html#provisioned-iops-storage\">I/O-Optimized storage</a>\n          that's designed to meet the needs of I/O-intensive graph workloads that\n          require predictable pricing with low I/O latency and consistent I/O throughput.</p>\n               <p>Neptune I/O-Optimized storage is only available starting with engine release 1.3.0.0.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.type = Types::ModifyDBClusterMessage
    ModifyDBClusterParameterGroupMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster parameter group to modify.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterParameterGroupMessage.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParametersList, location_name: 'Parameters', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of parameters in the DB cluster parameter group to modify.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterParameterGroupMessage.type = Types::ModifyDBClusterParameterGroupMessage
    ModifyDBClusterParameterGroupOutput.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters or numbers.</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <note>\n            <p>This value is stored as a lowercase string.</p>\n         </note>"}))
    ModifyDBClusterParameterGroupOutput.type = Types::ModifyDBClusterParameterGroupOutput
