    ModifyDBClusterSnapshotAttributeMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the DB cluster snapshot to modify the attributes for.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AttributeName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster snapshot attribute to modify.</p>\n         <p>To manage authorization for other Amazon accounts to copy or restore a manual DB cluster\n      snapshot, set this value to <code>restore</code>.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_add, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToAdd', traits: {"smithy.api#documentation" => "<p>A list of DB cluster snapshot attributes to add to the attribute specified by\n      <code>AttributeName</code>.</p>\n         <p>To authorize other Amazon accounts to copy or restore a manual DB cluster snapshot, set this\n      list to include one or more Amazon account IDs, or <code>all</code> to make the manual DB cluster\n      snapshot restorable by any Amazon account. Do not add the <code>all</code> value for any manual\n      DB cluster snapshots that contain private information that you don't want available to all Amazon\n      accounts.</p>"}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToRemove', traits: {"smithy.api#documentation" => "<p>A list of DB cluster snapshot attributes to remove from the attribute specified by\n      <code>AttributeName</code>.</p>\n         <p>To remove authorization for other Amazon accounts to copy or restore a manual DB cluster\n      snapshot, set this list to include one or more Amazon account identifiers, or <code>all</code> to\n      remove authorization for any Amazon account to copy or restore the DB cluster snapshot. If you\n      specify <code>all</code>, an Amazon account whose account ID is explicitly added to the\n      <code>restore</code> attribute can still copy or restore a manual DB cluster snapshot.</p>"}))
    ModifyDBClusterSnapshotAttributeMessage.type = Types::ModifyDBClusterSnapshotAttributeMessage
