    ModifyDBInstanceMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB instance identifier. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DBInstance.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyDBInstanceMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>Not supported by Neptune.</p>"}))
    ModifyDBInstanceMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The new compute and memory capacity of the DB instance, for example,\n      <code>db.m4.large</code>. Not all DB instance classes are available in all Amazon\n      Regions.</p>\n         <p>If you modify the DB instance class, an outage occurs during the change. The change is\n      applied during the next maintenance window, unless <code>ApplyImmediately</code> is specified\n      as <code>true</code> for this request.</p>\n         <p>Default: Uses existing setting</p>"}))
    ModifyDBInstanceMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The new DB subnet group for the DB instance. You can use this parameter to move your DB\n      instance to a different VPC.</p>\n         <p>Changing the subnet group causes an outage during the change. The change is applied during\n      the next maintenance window, unless you specify <code>true</code> for the\n      <code>ApplyImmediately</code> parameter.</p>\n         <p>Constraints: If supplied, must match the name of an existing DBSubnetGroup.</p>\n         <p>Example: <code>mySubnetGroup</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:db_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroupNameList, location_name: 'DBSecurityGroups', traits: {"smithy.api#documentation" => "<p>A list of DB security groups to authorize on this DB instance. Changing this setting\n      doesn't result in an outage and the change is asynchronously applied as soon as\n      possible.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match existing DBSecurityGroups.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to authorize on this DB instance. This change is\n      asynchronously applied as soon as possible.</p>\n         <p>Not applicable. The associated list of EC2 VPC security groups is managed by the DB\n      cluster. For more information, see <a>ModifyDBCluster</a>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match existing VpcSecurityGroupIds.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>Specifies whether the modifications in this request and any pending modifications are\n      asynchronously applied as soon as possible, regardless of the\n      <code>PreferredMaintenanceWindow</code> setting for the DB instance.</p>\n         <p> If this parameter is set to <code>false</code>, changes to the DB instance are applied\n      during the next maintenance window. Some parameter changes can cause an outage and are applied\n      on the next call to <a>RebootDBInstance</a>, or the next\n      failure reboot.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>Not supported by Neptune.</p>"}))
    ModifyDBInstanceMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to apply to the DB instance. Changing this setting\n      doesn't result in an outage. The parameter group name itself is changed immediately, but the\n      actual parameter changes are not applied until you reboot the instance without failover. The\n      db instance will NOT be rebooted automatically and the parameter changes will NOT be applied\n      during the next maintenance window.</p>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints: The DB parameter group must be in the same DB parameter group family as this\n      DB instance.</p>"}))
    ModifyDBInstanceMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>Not applicable. The retention period for automated backups is managed by the DB cluster.\n      For more information, see <a>ModifyDBCluster</a>.</p>\n         <p>Default: Uses existing setting</p>"}))
    ModifyDBInstanceMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p> The daily time range during which automated backups are created if automated backups are\n      enabled.</p>\n         <p>Not applicable. The daily time range for creating automated backups is managed by the DB\n      cluster. For more information, see <a>ModifyDBCluster</a>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format hh24:mi-hh24:mi</p>\n            </li>\n            <li>\n               <p>Must be in Universal Time Coordinated (UTC)</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range (in UTC) during which system maintenance can occur, which might\n      result in an outage. Changing this parameter doesn't result in an outage, except in the\n      following situation, and the change is asynchronously applied as soon as possible. If there\n      are pending actions that cause a reboot, and the maintenance window is changed to include the\n      current time, then changing this parameter will cause a reboot of the DB instance. If moving\n      this window to the current time, there must be at least 30 minutes between the current time\n      and end of the window to ensure pending changes are applied.</p>\n         <p>Default: Uses existing setting</p>\n         <p>Format: ddd:hh24:mi-ddd:hh24:mi</p>\n         <p>Valid Days: Mon | Tue | Wed | Thu | Fri | Sat | Sun</p>\n         <p>Constraints: Must be at least 30 minutes</p>"}))
    ModifyDBInstanceMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies if the DB instance is a Multi-AZ deployment. Changing this parameter doesn't\n      result in an outage and the change is applied during the next maintenance window unless the\n      <code>ApplyImmediately</code> parameter is set to <code>true</code> for this request.</p>"}))
    ModifyDBInstanceMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to upgrade to. Currently, setting this\n      parameter has no effect. To upgrade your database engine to the most recent release,\n      use the <a>ApplyPendingMaintenanceAction</a> API.</p>"}))
    ModifyDBInstanceMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Indicates that major version upgrades are allowed. Changing this parameter doesn't result\n      in an outage and the change is asynchronously applied as soon as possible.</p>"}))
    ModifyDBInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p> Indicates that minor version upgrades are applied automatically to the DB instance during\n      the maintenance window. Changing this parameter doesn't result in an outage except in the\n      following case and the change is asynchronously applied as soon as possible. An outage will\n      result if this parameter is set to <code>true</code> during the maintenance window, and a\n      newer minor version is available, and Neptune has enabled auto patching for that engine\n      version.</p>"}))
    ModifyDBInstanceMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>Not supported by Neptune.</p>"}))
    ModifyDBInstanceMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The new Provisioned IOPS (I/O operations per second) value for the instance.</p>\n         <p>Changing this setting doesn't result in an outage and the change is applied during the\n      next maintenance window unless the <code>ApplyImmediately</code> parameter is set to\n      <code>true</code> for this request.</p>\n         <p>Default: Uses existing setting</p>"}))
    ModifyDBInstanceMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>\n            <i>(Not supported by Neptune)</i>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:new_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p> The new DB instance identifier for the DB instance when renaming a DB instance. When you\n      change the DB instance identifier, an instance reboot will occur immediately if you set\n      <code>Apply Immediately</code> to true, or will occur during the next maintenance window if\n      <code>Apply Immediately</code> to false. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbinstance</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Not applicable. In Neptune the storage type is managed at the DB Cluster level.</p>"}))
    ModifyDBInstanceMessage.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which to associate the instance for TDE encryption.</p>"}))
    ModifyDBInstanceMessage.add_member(:tde_credential_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitiveString, location_name: 'TdeCredentialPassword', traits: {"smithy.api#documentation" => "<p>The password for the given ARN from the key store in order to access the device.</p>"}))
    ModifyDBInstanceMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>Indicates the certificate that needs to be associated with the instance.</p>"}))
    ModifyDBInstanceMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Not supported.</p>"}))
